widget.draw:
function draw(ctx, state, t) {
function fmt(v) { return Math.round(v * 100) / 100; }


  var w = state.w;
  var h = state.h;
  var kv = state.kv;
  var group = state.group;
  var qh = kv * group;
  var ratio = kv / (kv * group);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = "#222222";
  ctx.font = "12px sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillText("not to scale", 24, 22);
  ctx.fillText("kv = " + fmt(kv), 24, 44);
  ctx.fillText("group = " + fmt(group), 24, 62);
  ctx.fillText("q_heads = " + fmt(qh), 24, 84);
  ctx.fillText("cache_ratio = " + fmt(ratio), 24, 102);
  var x0 = 240;
  var tr = 160;
  var i = 0;
  var j = 0;
  ctx.strokeStyle = "#222222";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x0, 36);
  ctx.lineTo(x0 + tr, 36);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0, 30);
  ctx.lineTo(x0, 42);
  ctx.stroke();
  ctx.fillText("MQA = " + fmt(1), x0 - 10, 58);
  ctx.fillText("kv track", x0 + tr + 8, 40);
  ctx.beginPath();
  ctx.moveTo(x0, 74);
  ctx.lineTo(x0 + tr, 74);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0, 68);
  ctx.lineTo(x0, 80);
  ctx.stroke();
  ctx.fillText("MHA = " + fmt(1), x0 - 10, 96);
  ctx.fillText("group track", x0 + tr + 8, 78);
  var px = x0 + (kv - 1) * (tr / 7);
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(px - 3, 28, 6, 16);
  var gx = x0 + (group - 1) * (tr / 7);
  ctx.fillRect(gx - 3, 66, 6, 16);
  var bx = 60;
  var step = 66;
  var qy = 130;
  var ky = 280;
  for (i = 0; i < kv; i++) {
    var qhh = group * 14;
    var qx = bx + i * step;
    ctx.fillStyle = "#1f4b99";
    ctx.fillRect(qx, qy, 46, qhh);
    ctx.strokeStyle = "#1f4b99";
    ctx.lineWidth = 1;
    ctx.strokeRect(qx, qy, 46, qhh);
    ctx.fillStyle = "#222222";
    ctx.fillText("Q", qx - 14, qy + qhh / 2);
    ctx.fillStyle = "#c4512c";
    ctx.fillRect(qx, ky, 46, 30);
    ctx.fillStyle = "#222222";
    ctx.fillText("KV", qx - 20, ky + 18);
    ctx.strokeStyle = "#555555";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(qx + 23, qy + qhh);
    ctx.lineTo(qx + 23, ky);
    ctx.stroke();
    for (j = 0; j < group; j++) {
      ctx.strokeStyle = "#ffffff";
      ctx.beginPath();
      ctx.moveTo(qx, qy + (j + 1) * 14);
      ctx.lineTo(qx + 46, qy + (j + 1) * 14);
      ctx.stroke();
    }
  }
  ctx.fillStyle = "#222222";
  ctx.fillText("Q blocks share KV block", 60, 122);
  ctx.fillText("KV cache grows with kv", 60, 332);
}
